function [dp] = pump_pressure_for_torque(tau, l, s, d)
%PUMP_PRESSURE_FOR_TORQUE  The pump pressure that gives a torque: dp = tau L/(2 S A), A = pi d^2/4.
%   tau: real[N m] (passed in m^2 kg/s^2)
%   l: real[m] (passed in m)
%   s: real[m^2] (passed in m^2)
%   d: real[mm] (passed in m)
%   returns dp: real[Pa] (passed in kg/(m s^2))
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    dp = 0;
    a = ((pi * asils.pc.ipow(d, 2)) / 4);
    dp = ((tau * l) / ((2 * s) * a));
end
